  "Could not create the quiz:": { es: "No se pudo crear el cuestionario:", ar: "تعذّر إنشاء الاختبار:", zh: "无法创建测验：", sw: "Haikuweza kutengeneza jaribio:", sv: "Kunde inte skapa quizet:", de: "Quiz konnte nicht erstellt werden:", pt: "Não foi possível criar o quiz:", fr: "Impossible de créer le quiz :" },
  "Tick at least one question type.": { es: "Marca al menos un tipo de pregunta.", ar: "اختر نوعًا واحدًا على الأقل من الأسئلة.", zh: "请至少勾选一种题型。", sw: "Weka alama kwenye angalau aina moja ya swali.", sv: "Kryssa i minst en frågetyp.", de: "Hake mindestens eine Fragenart an.", pt: "Marque pelo menos um tipo de pergunta.", fr: "Cochez au moins un type de question." },
  "Art in the style of Sonia Delaunay – click for more": { es: "Arte al estilo de Sonia Delaunay: haz clic para saber más", ar: "رسم بأسلوب سونيا ديلوناي – انقر لمعرفة المزيد", zh: "索尼娅·德劳内风格的插画——点击了解更多", sw: "Sanaa kwa mtindo wa Sonia Delaunay – bofya kujua zaidi", sv: "Konst i Sonia Delaunays stil – klicka för mer", de: "Kunst im Stil von Sonia Delaunay – klicken für mehr", pt: "Arte no estilo de Sonia Delaunay – clique para saber mais", fr: "Illustration dans le style de Sonia Delaunay – cliquez pour en savoir plus" },
  "Zoom in": { es: "Acercar", ar: "تكبير", zh: "放大", sw: "Kuza", sv: "Zooma in", de: "Vergrößern", pt: "Aproximar", fr: "Zoom avant" },
